package org.racedaydreams.domain.strength;

import java.util.List;

/** Movement-specific original guidance, kept separate from the older priority-guide groups. */
final class AdditionalTechniqueGuides {
    private AdditionalTechniqueGuides() {}

    static TechniqueGuide forExercise(String id) {
        return switch (id) {
            case "goblet-squat" -> guide("squat", "Hold one dumbbell vertically against your chest with both hands; take a comfortable stance and brace.", "Bend hips and knees together, keep your whole foot down, then stand through your feet.", "Quadriceps and glutes", List.of("Keep the weight close to your chest", "Let knees follow the toes", "Choose a depth you can control"), List.of("Letting heels lift", "Collapsing the trunk", "Bouncing beyond a comfortable depth"), "Leg Press", "Back Squat");
            case "dumbbell-row" -> guide("row", "Support one hand and knee on a stable bench; plant the opposite foot and hold a dumbbell in the free hand.", "With a steady trunk, pull the dumbbell toward your hip and lower it smoothly; change sides as prescribed.", "Lats, upper back and elbow flexors", List.of("Keep hips and shoulders steady", "Draw the elbow back", "Let the arm extend under control"), List.of("Rotating the whole trunk to lift", "Jerking the weight", "Shrugging instead of rowing"), "Seated Cable Row", "Chest-Supported Row");
            case "push-up" -> guide("press", "Place hands on a stable floor below your shoulders and extend your legs with toes supported; use an incline if needed.", "Lower your chest with elbows bending comfortably away from the trunk, then press back to a controlled body line.", "Chest, triceps and trunk", List.of("Keep shoulders, hips and ankles aligned", "Breathe throughout", "Use an easier incline when control fades"), List.of("Letting the hips sag", "Flaring elbows to an uncomfortable angle", "Shortening every repetition to keep going"), "Dumbbell Bench Press", "Machine Chest Press");
            case "barbell-curl" -> guide("curl", "Stand steadily holding a barbell in an underhand grip, arms alongside the trunk and wrists comfortable.", "Bend the elbows to raise the bar without leaning back; lower to the starting position slowly.", "Biceps and other elbow flexors", List.of("Keep upper arms beside your trunk", "Keep wrists steady", "Use a manageable load"), List.of("Swinging the hips to lift", "Leaning backwards", "Dropping the lowering phase"), "EZ-Bar Curl", "Dumbbell Curl");
            case "hammer-curl" -> guide("curl", "Hold a dumbbell in each hand with palms facing inwards and elbows beside your trunk.", "Bend the elbows while keeping the neutral grip, then lower the dumbbells without swinging.", "Elbow flexors and forearms", List.of("Keep palms facing each other", "Steady the upper arms", "Control both directions"), List.of("Rocking backwards", "Bending wrists to finish", "Using momentum from the shoulders"), "Dumbbell Curl", "Cable Curl");
            case "lateral-raise" -> guide("raise", "Stand with manageable dumbbells at your sides, softly bent elbows and a stable trunk.", "Raise arms outwards to about shoulder height within a comfortable range, then lower slowly.", "Shoulders, particularly the lateral deltoids", List.of("Keep a small elbow bend", "Use a light controllable load", "Keep neck and shoulders comfortable"), List.of("Heaving the weights upwards", "Shrugging to finish", "Lifting beyond a comfortable range"), "Cable Lateral Raise", "Machine Shoulder Press");
            case "triceps-pressdown" -> guide("extension", "Attach a short bar to a high pulley; stand facing it with elbows beside the ribs and forearms bent.", "Extend the elbows to press the bar down, then return slowly without moving the upper arms forwards.", "Triceps", List.of("Keep elbows beside the ribs", "Keep wrists comfortable", "Control the return"), List.of("Leaning your whole body onto the bar", "Swinging the upper arms", "Letting the cable snap back"), "Rope Pressdown", "Dumbbell Overhead Extension");
            case "dead-bug" -> guide("core", "Lie on your back with knees bent above hips and arms reaching upwards; brace gently and breathe.", "Extend one leg and the opposite arm away, only as far as you can control the trunk; return and alternate.", "Trunk stabilisers", List.of("Move opposite arm and leg", "Keep the trunk steady", "Shorten the reach if your back arches"), List.of("Holding your breath", "Reaching too far to keep control", "Rushing the alternating movements"), "Bird Dog", "Plank");
            case "bird-dog" -> guide("core", "Begin on hands and knees with hands below shoulders and knees beneath hips.", "Reach one arm forward and the opposite leg backwards without turning the pelvis; return and alternate.", "Trunk, glutes and back stabilisers", List.of("Keep hips level", "Reach long rather than high", "Move slowly while breathing"), List.of("Overarching the back", "Twisting to lift higher", "Shifting weight abruptly"), "Dead Bug", "Plank");
            case "seated-calf-raise" -> guide("calf", "Adjust the machine thigh pad above your knees; sit with forefeet on the footplate and heels free to move.", "Lift the heels to raise the resistance, pause briefly, then lower slowly through a comfortable ankle range.", "Calves, with bent-knee emphasis", List.of("Keep forefeet supported", "Keep thighs under the pad", "Control the full comfortable range"), List.of("Bouncing through the bottom", "Lifting the thighs off the seat", "Using too much load for controlled movement"), "Standing Calf Raise", "Leg Press Calf Raise");
            case "incline-dumbbell-press" -> guide("press", "Set an inclined bench to a moderate angle, support your back and head, plant your feet and bring dumbbells beside the upper chest.", "Press above the upper chest, then lower under control without arching away from the bench.", "Upper chest, front shoulders and triceps", List.of("Keep feet planted", "Keep forearms beneath the weights", "Choose a comfortable lowering depth"), List.of("Letting the weights drift behind the shoulders", "Bouncing the weights", "Overarching the back"), "Dumbbell Bench Press", "Machine Chest Press");
            case "dumbbell-curl" -> guide("curl", "Stand holding a dumbbell in each hand with palms forwards and upper arms beside your trunk.", "Bend the elbows to lift the weights toward the shoulders, then lower without swaying.", "Biceps and other elbow flexors", List.of("Keep upper arms steady", "Keep wrists comfortable", "Control the return"), List.of("Swinging the hips", "Leaning back to finish", "Letting the weights drop"), "Barbell Curl", "Hammer Curl");
            case "ez-bar-curl" -> guide("curl", "Hold the angled grips of an EZ bar with palms turned upwards and elbows beside your trunk.", "Curl the bar by bending the elbows, then lower smoothly without moving your whole body.", "Biceps and other elbow flexors", List.of("Use comfortable angled grips", "Keep upper arms beside ribs", "Lower smoothly"), List.of("Driving the bar with hip movement", "Bending wrists under load", "Losing control at the bottom"), "Barbell Curl", "Dumbbell Curl");
            case "seated-leg-curl" -> guide("curl", "Adjust the knee pivot, backrest, thigh restraint and lower-leg roller; keep your back and thighs supported.", "Bend the knees to bring the roller down and back beneath the seat, then extend slowly through the comfortable range.", "Hamstrings", List.of("Keep knees near the machine pivot", "Secure thighs beneath the pad", "Control both directions"), List.of("Lifting hips off the seat", "Jerking the roller", "Using an uncomfortable machine adjustment"), "Lying Leg Curl", "Sliding Leg Curl");
            case "leg-extension" -> guide("extension", "Sit against the machine backrest, align knees with its pivot and place the shin pad just above your ankles.", "Extend the knees to lift the pad, then lower smoothly through a comfortable range without kicking.", "Quadriceps", List.of("Keep hips and back supported", "Control the lowering", "Choose a comfortable range"), List.of("Kicking the load upwards", "Lifting hips off the seat", "Using a pad against the feet instead of shins"), "Leg Press", "Goblet Squat");
            case "suitcase-carry" -> guide("carry", "Lift one manageable dumbbell beside your hip; keep the opposite hand free and stand with shoulders level.", "Walk with controlled steps without leaning sideways, then set the weight down deliberately and change sides.", "Grip and trunk stabilisers", List.of("Keep shoulders level", "Take steady steps", "Train both sides as prescribed"), List.of("Leaning away from the load", "Swinging the dumbbell", "Continuing after grip or posture deteriorates"), "Farmer’s Carry", "Front Rack Carry");
            case "weighted-plank" -> guide("plank", "Set forearms beneath shoulders and use a small load that can be placed securely over the mid-back with help if needed; keep it away from the neck and lower back.", "Support on forearms and toes with a steady body line and breathe; stop the hold before control or load security deteriorates.", "Trunk stabilisers", List.of("Keep the load secure", "Breathe throughout", "Use a bodyweight hold if alone or unsure"), List.of("Balancing an unstable stack", "Letting hips sag", "Continuing when the plate moves"), "Plank", "Dead Bug");
            case "dead-hang" -> guide("hang", "Grip a secure overhead bar with both hands and use a stable step to reach it if needed.", "Allow the feet to leave their support and hold a comfortable controlled hang; return safely to support to finish.", "Grip, forearms and shoulder support", List.of("Use a secure bar", "Keep breathing", "Stop before grip fails"), List.of("Jumping to an uncertain grip", "Swinging unnecessarily", "Hanging through shoulder discomfort"), "Lat Pulldown", "Pull-Up");
            case "pallof-press" -> guide("core", "Stand side-on to a chest-height cable with a stable stance; hold its handle in both hands at the centre of your chest.", "Press the hands straight ahead while resisting rotation, pause briefly and return; change sides as prescribed.", "Trunk stabilisers", List.of("Keep ribs and pelvis facing forwards", "Use a manageable cable load", "Press without twisting"), List.of("Turning toward the pulley", "Leaning sideways", "Holding your breath to finish"), "Side Plank", "Dead Bug");
            case "ab-wheel" -> guide("core", "Kneel on a mat with both hands holding the wheel axle beneath your shoulders and brace gently.", "Roll forward only as far as you can maintain a controlled trunk, then pull the wheel back toward the knees.", "Trunk stabilisers and shoulder support", List.of("Keep knees supported", "Use a short range first", "Keep breathing and ribs controlled"), List.of("Letting the lower back sag", "Rolling farther than you can return", "Rushing the return"), "Plank", "Dead Bug");
            default -> null;
        };
    }

    private static TechniqueGuide guide(String pattern, String setup, String movement, String muscles,
                                         List<String> cues, List<String> mistakes, String... alternatives) {
        return new TechniqueGuide(pattern, setup, movement, cues, mistakes, muscles, List.of(alternatives));
    }
}
